head.script:

	// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {
        var row = 10;
        var col = 5;
        var data = [];
        for(var i = 0; i < row; i++){
            for(var j = 0; j < col; j++){
                data.push((i * row + j) + ""); 
            }
        }
        dataList1.setData(data);
        	};




	// 확장된 기능1
    scwin.trigger3_onclick = function(e) {
        dataList1.setIgnoreStatus(true);
    };
    // 확장된 기능2
    scwin.trigger4_onclick = function(e) {
        dataList1.setIgnoreStatus(false);
    };


	scwin.Dbclick = function(id) {
		var el = scwin.__getDom(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal1 = function() {
		return (document.getElementById('gridView1_headerRowStatus_bodyRow_0') || document.getElementById('mf_gridView1_headerRowStatus_bodyRow_0')).classList.contains('w2grid_rowStatus_R');
	}
	scwin.checkVal2 = function() {
		return (document.getElementById('gridView1_headerRowStatus_bodyRow_0') || document.getElementById('mf_gridView1_headerRowStatus_bodyRow_0')).classList.contains('w2grid_rowStatus_U');
	}	
	scwin.checkVal3 = function() {
		return (document.getElementById('gridView1_headerRowStatus_bodyRow_1') || document.getElementById('mf_gridView1_headerRowStatus_bodyRow_1')).classList.contains('w2grid_rowStatus_R');
	}
